export interface SearchTrendingCategory {
    name: string;
    url: string;
    count?: number;
}
export interface SearchTrendingProduct {
    name: string;
    url: string;
}
export interface SearchPopularItem {
    id: string | number;
    name: string;
}
export interface SearchPopularResponse {
    success: boolean;
    status: number;
    data: {
        products: SearchPopularItem[];
        categories: SearchPopularItem[];
    };
}
export interface SearchLabels {
    searchPlaceholder: string;
    noOptions: string;
    outOfStock: string;
    close: string;
    back: string;
    remove: string;
    searchHistory: string;
    trendingCategories: string;
    mostSearched: string;
    searchSuggestions: string;
    categories: string;
    searchResults: string;
    /** Contains the lang.js `:word` placeholder - interpolated at render time, not re-fetched. */
    searchViewAllTemplate: string;
}
